EXT[33] = dict(
 intermediate_add="""**Common vs random on the same data (BCG, 13 trials, log RR).** Common-effect pooling gives ln RR = **−0.430** (SE 0.0405; RR 0.65) with Q = **152.23** on 12 df; REML random-effects pooling gives **−0.715** (SE 0.180; RR 0.49). The two estimates differ because the common-effect model gives the huge trials (small variances) almost all the weight, whereas random effects add τ² = 0.313 to every variance and so spread weight more evenly. The CI of the common-effect model (±0.079) is far narrower than the random-effects CI (±0.352) - a precision that is only valid if all trials estimate the *same* effect, which Q = 152.23 flatly contradicts. Rule of thumb for reporting: choose the model on scientific grounds before seeing Q, and if you report a common-effect model, say what the single true effect means.""",
 quiz_add=[dict(q="Common-effect pooled ln RR for the 13 BCG trials:", opts=["-0.430","-0.715","-0.150","0.313"], ans=0, why="Inverse-variance weights dominated by large trials; random-effects gives -0.715.", numeric=True)],
 mistakes_add=["Choosing common-effect because Q is non-significant in a small set of studies."])

